/* Bhashini Website Translation Plugin v3 — widget placement + dropdown styling */

.bhashini-plugin-container svg,
#bhashini-translation svg,
.bhashini-translator-widget svg {
  width: 24px;
  height: 24px;
}

/*
 * Initial injection mount — keep in DOM for script init, hide only after widget moves out.
 */
header.mb-common-header > .mb-common-header__bhashini-mount:not(.mb-common-header__bhashini-mount--empty) {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
  float: none !important;
  margin: 0 !important;
  padding: 0 !important;
}

header.mb-common-header > .mb-common-header__bhashini-mount--empty {
  display: none !important;
}

.bhashini-dropdown-content {
  bottom: auto !important;
  right: -75px;
  scrollbar-width: thin;
}

.bhashini-dropdown-content .language-option {
  text-align: left !important;
}

/* Slot containers — inline with header items */
#bhashini-desktop-header,
#bhashini-mobile-header {
  display: inline-block;
  vertical-align: middle;
  line-height: 1;
}

#bhashini-desktop-header .bhashini-dropdown,
#bhashini-mobile-header .bhashini-dropdown,
#bhashini-translation {
  display: inline-block;
  vertical-align: middle;
  position: relative;
}

/* Desktop gov strip — white icon */
.header-top #bhashini-desktop-header .bhashini-dropdown-btn-icon svg path {
  fill: #ffffff;
}

/* Mobile — main header row */
@media only screen and (max-width: 999px) {
  .bhashini-dropdown-content {
    top: 40px !important;
    right: -40px;
  }

  #bhashini-mobile-header .bhashini-dropdown-btn-icon svg path,
  #bhashini-translation .bhashini-dropdown-btn-icon svg path {
    fill: #000000 !important;
  }
}

/* =========================
   HEADER (custom classes) — shared by Header + Header2
   Source merged from:
   - app/webroot/css/default.css
   - View/Elements/header_external.ctp (inline style)
   ========================= */

/* Scoped float helpers (replacing host default.css .f-left / .f-right names) */
header.mb-common-header .f-hd-left {
  float: left;
}

header.mb-common-header .f-hd-right {
  float: right;
}

/* No underlines on any header links (beats host theme defaults). */
header.mb-common-header a,
header.mb-common-header a:hover,
header.mb-common-header a:focus,
header.mb-common-header a:focus-visible,
header.mb-common-header a:visited,
header.mb-common-header a:active {
  text-decoration: none !important;
}

#mb-nav-desktop-main {
  padding: 0;
}

/*
 * Desktop nav row — keep links + auth buttons on one line (Bootstrap .navbar flex-wrap
 * otherwise pushes Sign In / Register below the ul when the menu is wide).
 */
@media (min-width: 992px) {
  header.mb-common-header #mb-nav-desktop-main.navbar {
    display: flex;
    flex-wrap: nowrap;
    align-items: center;
    justify-content: flex-end;
    gap: 0;
  }

  header.mb-common-header #mb-nav-desktop-main .menu_nav1 {
    display: inline-flex;
    flex: 0 1 auto;
    flex-wrap: nowrap;
    align-items: center;
    list-style: none;
    margin: 0;
    padding: 0;
  }

  header.mb-common-header #mb-nav-desktop-main > .mb-common-header__auth-btn,
  header.mb-common-header #mb-nav-desktop-main > .mb-common-header__register-link {
    flex: 0 0 auto;
    align-self: center;
    margin-left: 12px;
    vertical-align: middle;
  }

  header.mb-common-header #mb-nav-desktop-main > .mb-common-header__profile,
  header.mb-common-header #mb-nav-desktop-main > .chat-toggler.mb-common-header__profile {
    flex: 0 0 auto;
    align-self: center;
    margin-left: 12px;
  }

  header.mb-common-header #mb-nav-desktop-main > .btn-group {
    flex: 0 0 auto;
    align-self: center;
  }
}

/* top strip */
.header-top {
  background: #081854;
  position: relative;
}

.header-top .skip01 {
  color: #ffffff;
  line-height: 28px;
  font-size: 13px;
  font-weight: 600;
  padding-right: 15px;
}

.header-top .partition {
