/* events/program custom dropdown */
.dropdown_evnt_prog {
  position: relative;
  display: inline-block;
}

.dropevent {
  background-color: #ffffff;
  color: #000000;
  padding: 6px 4px;
  font-size: 13px;
  font-weight: 600;
  border: none;
}

.dropevent_content {
  display: none;
  position: absolute;
  background-color: #fff;
  min-width: 180px;
  z-index: 1;
  border: 1px solid #dcdcdc;
  border-radius: 4px;
  left: -25px;
}

/* Only the top “notch” caret on each panel — not chevrons on nested group buttons */
.dropevent_content > .fa.fa-caret-up {
  position: absolute;
  top: -10px;
  left: 43%;
  color: #bc4717;
}

.dropevent_content a {
  color: black;
  border-bottom: 1px solid #dcdcdc;
  padding: 12px 16px;
  text-decoration: none;
  display: block;
  font-size: 13px;
  font-weight: 600;
}

.dropevent_content a:hover {
  background-color: #fff;
}

/* Only the direct submenu panel opens — not nested .dropevent_content descendants (fixes inner groups auto-expanding). */
/* Default chevron rotation for all dropdowns */
.dropevent i.fa-chevron-down {
  transform: rotate(-90deg);
  transition: transform 0.3s ease-in-out;
}

.dropdown_evnt_prog:hover > .dropevent_content {
  display: block;
}

/* Main menu chevron rotation on click (active state) */
.dropdown_evnt_prog.active > .dropevent i.fa-chevron-down {
  transform: rotate(0deg);
}

/* Nested dropdown chevron rotation on click (active state) */
.dropevent_content .dropdown_evnt_prog.active > .dropevent i.fa-chevron-down {
  transform: rotate(0deg);
}

/* Nested dropdown inside panel (multilevel nav from API) */
.dropevent_content .dropdown_evnt_prog {
  display: block;
  width: 100%;
}

.dropevent_content .dropdown_evnt_prog .dropevent {
  width: 100%;
  text-align: left;
  border-top: 1px solid #dcdcdc;
}

.dropevent_content .dropdown_evnt_prog .dropevent_content {
  left: 100%;
  top: 0;
  margin-left: 2px;
}

.dropevent_content .dropdown_evnt_prog:hover > .dropevent_content {
  display: block;
}

