.social-icons .icon span {
  margin-left: 4px;
  white-space: nowrap;
  opacity: 0;
  transform: translateX(-10px);
  transition: all 0.3s ease;
  font-size: 13px;
}

.twitter-color {
  color: #000;
}

.instagram-color {
  color: #cf188a;
}

.facebook-color {
  color: #4676ed;
}

.linkedin-color {
  color: #4467ad;
}

.whatsapp-color {
  color: #00c169;
}

.youtube-color {
  color: #e52d27;
}

@media (hover: hover) and (pointer: fine) {
  .social-icons .icon:hover {
    width: 100px;
    justify-content: flex-start;
  }

  .social-icons .icon:hover span {
    opacity: 1;
    transform: translateX(0);
  }
}

.mb-20 {
  margin-bottom: 1.25rem;
}

.whitetext img {
  vertical-align: middle;
}

/* “Powered by” + Digital India logo — single horizontal row (web / tablet / mobile) */
#footer_external .mb-common-footer__powered-inner {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.35rem 0.75rem;
}

#footer_external .mb-common-footer__powered-by {
  color: #495059 !important;
}

#footer_external .whitetext.mb-common-footer__powered-logo {
  color: inherit !important;
  display: inline-flex;
  align-items: center;
  line-height: 1;
}

#footer_external .mb-common-footer__powered-logo img {
  display: block;
  flex-shrink: 0;
}
